function [ac,per] = mypulseac(nmat,dt,resonance);if nargin<2    dt=0.01;endif nargin < 3    resonance = 1;endwarning offMAXLAG = 1.5;sz = floor(MAXLAG/dt);per = dt*(1:(1+sz))';ac = zeros(sz+1,1);if size(nmat,1)<2 	%disp('empty');	return; endp=conv(brown(nmat,dt),mttbgauss(-0.1:dt:0.1,0,0.02));o=ones(size(p));xp=xcorr(p,p,round(MAXLAG/dt),'coeff');xo=xcorr(o,o,round(MAXLAG/dt),'coeff');xp=xp./xo;%xxp = reshape(xp(i1:i2),sz+1,1).*(1:sz+1)'/(sz+1)*10;i1 = (length(xp)+1)/2;i2 = min(i1 + sz, length(xp));ac = xp(i1:i2);p = dt*(1:length(ac));if resonance    % apply resonance model of Van Noorden & Moelants    %f0=2.193; b=0.5;     %f=1./p; a1=(f0*f0-f.*f).^2+b*f.^2; a2=f0^4+f.^4;    %w=(1./sqrt(a1))-(1./sqrt(a2));    w = max(1 - 0.25*(log2(p/0.5)).^2, 0);    ac = ac(:).*w(:);    %ac = ac';else    ac = ac(:);end